use std::slice;
const M:i64=128;const R:usize=9;const E:i32=-1;
#[derive(Clone,Copy)]struct Node{v:i64,child:i32,sibling:i32,degree:usize}
struct Heap{nodes:[Node;128],roots:[i32;R],used:usize,size:usize}
impl Heap{fn new()->Self{Self{nodes:[Node{v:0,child:E,sibling:E,degree:0};128],roots:[E;R],used:0,size:0}}fn link(&mut self,a:i32,b:i32)->i32{let(p,c)=if self.nodes[a as usize].v<self.nodes[b as usize].v{(a,b)}else{(b,a)};let(p,c)=(p as usize,c as usize);self.nodes[c].sibling=self.nodes[p].child;self.nodes[p].child=c as i32;self.nodes[p].degree+=1;p as i32}fn add(&mut self,mut r:i32){let mut d=self.nodes[r as usize].degree;while self.roots[d]!=E{r=self.link(r,self.roots[d]);self.roots[d]=E;d+=1;}self.roots[d]=r;}fn insert(&mut self,v:i64){let r=self.used as i32;self.used+=1;self.nodes[r as usize]=Node{v,child:E,sibling:E,degree:0};self.size+=1;self.add(r);}fn minroot(&self)->i32{let mut b=E;for &r in &self.roots{if r!=E&&(b==E||self.nodes[r as usize].v<self.nodes[b as usize].v){b=r;}}b}fn extract(&mut self)->i64{let b=self.minroot() as usize;let d=self.nodes[b].degree;let v=self.nodes[b].v;self.roots[d]=E;let mut c=self.nodes[b].child;while c!=E{let i=c as usize;let next=self.nodes[i].sibling;self.nodes[i].sibling=E;self.add(c);c=next;}self.size-=1;v}}
#[no_mangle]pub unsafe extern "C" fn binomial_heap(input:*const i64,len:usize,out:*mut u8,cap:usize)->i64{if input.is_null()||len<1{return -1;}let a=slice::from_raw_parts(input,len);if a[0]<0||a[0]>M||len!=1+2*a[0]as usize{return -1;}let n=a[0]as usize;let(mut q,mut size)=(0usize,0usize);for i in 0..n{let(op,v)=(a[1+2*i],a[2+2*i]);if op==0{if v<i32::MIN as i64||v>i32::MAX as i64{return -1;}size+=1;}else if(1..=3).contains(&op){if v!=0||((op==1||op==2)&&size==0){return -1;}if op==2{size-=1;}q+=1;}else{return -1;}}let need=q*8;if cap<need||(need>0&&out.is_null()){return -2;}let mut h=Heap::new();let mut w=0;for i in 0..n{let(op,v)=(a[1+2*i],a[2+2*i]);let r=if op==0{h.insert(v);continue;}else if op==1{h.nodes[h.minroot()as usize].v}else if op==2{h.extract()}else if h.size==0{1}else{0};let bits=r as u64;for b in 0..8{*out.add(w*8+b)=(bits>>(b*8))as u8;}w+=1;}w as i64}
